AK_TWILIGHT.catFood = [{"t":"荤食","ok":[{"id":"niurou","title":"牛肉","summary":"煮熟瘦牛肉可少量，注意过敏。","body":"去油去调味。部分猫对牛肉过敏。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895eb470af1_1787387572.jpg"},{"id":"yangrou","title":"羊肉","summary":"熟瘦羊肉可少量，膻味有的猫不吃。","body":"去油去调味。过敏个体需观察。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ef77ca12_1787387639.jpg"},{"id":"jirou","title":"鸡肉","summary":"去骨、原味熟鸡胸可作为零食。","body":"煮熟无油无盐。必须去骨。不能替代完整猫粮。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e926145b_1787387538.jpg"},{"id":"yarou","title":"鸭肉","summary":"熟瘦鸭肉可少量，常见于过敏配方。","body":"去皮去油去骨。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895efad55d1_1787387642.jpg"},{"id":"turou","title":"兔肉","summary":"低脂熟兔肉可少量，部分过敏猫会用到。","body":"去骨煮熟。仍需完整营养配方。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895eddde13c_1787387613.jpg"},{"id":"jigan","title":"鸡肝","summary":"营养浓、维生素A易过量。","body":"煮熟极少次数。不能天天喂肝，更不能当主食。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e8d55c35_1787387533.jpg"},{"id":"anchun","title":"鹌鹑","summary":"去骨熟鹌鹑可少量，注意骨头。","body":"完全煮熟并去骨后可作零食。生的有细菌风险。不能当唯一主食。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e633682a_1787387491.jpg"},{"id":"sanwenyv","title":"三文鱼","summary":"熟的可偶尔；生的有寄生虫风险。","body":"人用刺身不要直接喂。长期只喂鱼会营养不全。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ec90a27e_1787387593.jpg"},{"id":"jinqiangyv","title":"金枪鱼","summary":"可偶尔，长期当主食会营养不全。","body":"人用金枪鱼盐和汞风险更高。主食请用全价猫粮。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e90b40f0_1787387536.jpg"},{"id":"xueyv","title":"鳕鱼","summary":"去刺熟鳕鱼可少量。","body":"确认去刺。长期单一鱼种不合适。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ef263c77_1787387634.jpg"},{"id":"xia","title":"虾","summary":"去壳熟虾可极少，过敏常见。","body":"不要油爆虾和虾壳。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ee305df7_1787387619.jpg"},{"id":"shujidan","title":"熟鸡蛋","summary":"完全煮熟后可少量添加。","body":"切碎拌粮，注意不过量。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ed89e26d_1787387608.jpg"}],"no":[{"id":"jigutou","title":"鸡骨头","summary":"熟骨易碎，扎伤和卡住风险高。","body":"不要给油炸或炖过的鸡骨。连骨喂养属于专业生骨肉范畴。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e8f086f5_1787387535.jpg"},{"id":"yvgu","title":"鱼骨","summary":"细刺扎伤风险高。","body":"不要给鱼骨架。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895f04de270_1787387652.jpg"},{"id":"chayedan","title":"茶叶蛋","summary":"蛋本身可熟食，茶叶和盐是问题。","body":"茶叶蛋盐高、有茶叶成分。若给蛋，用原味水煮蛋更合适。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e6d5319f_1787387501.jpg"},{"id":"pidan","title":"皮蛋","summary":"碱和盐都很高。","body":"不要给皮蛋。熟鸡蛋更合适。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895eb97de6e_1787387577.jpg"},{"id":"pangxie","title":"螃蟹","summary":"甲壳和调味是问题，海鲜过敏也常见。","body":"不要给蟹黄蟹壳。原味熟蟹肉也非必需。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895eb7c4e10_1787387575.jpg"},{"id":"shengjidan","title":"生鸡蛋","summary":"细菌和生蛋清问题。","body":"不建议生喂。完全煮熟更好。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ed1972ff_1787387601.jpg"},{"id":"feirou","title":"肥肉","summary":"高脂容易胰腺炎和肠胃翻车。","body":"不要把肥肉边当零食。瘦肉去油去调味才可能作为偶尔奖励。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e7aa26cd_1787387514.jpg"},{"id":"xianyadan","title":"咸鸭蛋","summary":"盐极高。","body":"不要给。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ee6669b5_1787387622.jpg"},{"id":"larou","title":"腊肉","summary":"极咸、熏制、高脂。","body":"不是猫的食物。盐分对肾脏负担大。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ea030009_1787387552.jpg"},{"id":"zhaji","title":"炸鸡","summary":"油、盐、调料。骨头更危险。","body":"不要给。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895f083f159_1787387656.jpg"},{"id":"zhangyv","title":"章鱼","summary":"难消化，调味常见。","body":"不是适合的猫零食。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895f09ec0d5_1787387657.jpg"},{"id":"yvtou","title":"鱼头","summary":"刺、盐和调味都是问题。","body":"不要给红烧鱼头。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895f068ece8_1787387654.jpg"}]},{"t":"蔬菜","ok":[{"id":"nangua","title":"南瓜","summary":"蒸熟南瓜泥可少量，有人用来调节粪便。","body":"原味无糖。不是所有软便都适合自行加南瓜。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895eaf6f80b_1787387567.jpg"},{"id":"hongshu","title":"红薯","summary":"蒸熟去皮可少量，纤维较多。","body":"不要红薯干、糖红薯和油炸。肠胃敏感者谨慎。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e817be03_1787387521.jpg"},{"id":"qiezi","title":"茄子","summary":"茄科，未熟部分更不宜。","body":"不是猫需要的食物。炒茄子调味更不行。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ec23f79f_1787387586.jpg"},{"id":"donggua","title":"冬瓜","summary":"煮软无调味可少量，帮助部分猫增加水分。","body":"去皮煮软，不放盐。不是主食，肠胃敏感者从极少量开始。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e75a2bd8_1787387509.jpg"},{"id":"tudou","title":"土豆","summary":"生土豆不宜；熟的淀粉高。","body":"必须煮熟去皮。不是猫的主食。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895edc15e2d_1787387612.jpg"},{"id":"wandou","title":"豌豆","summary":"煮软少量。胀气可能发生。","body":"不要盐豌豆罐头。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895edfa43d9_1787387615.jpg"},{"id":"xilanhua","title":"西兰花","summary":"煮软少量。产气可能发生。","body":"完全煮熟。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895eeb7dba2_1787387627.jpg"},{"id":"shanyao","title":"山药","summary":"蒸熟去皮少量。生山药刺激。","body":"必须做熟。部分猫对淀粉不耐受。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ecaaa95b_1787387594.jpg"},{"id":"huluobo","title":"胡萝卜","summary":"煮软切碎可少量，生的难消化。","body":"蒸或煮到软。不能替代肉类营养。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e867e2e8_1787387526.jpg"},{"id":"shengcai","title":"生菜","summary":"少量叶片，营养贡献有限。","body":"洗干净。农药要冲掉。不吃就算了。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ece147f5_1787387598.jpg"},{"id":"juanxincai","title":"卷心菜","summary":"产气，煮软后仍非优选。","body":"多数猫不需要蔬菜。若给，煮软极少量。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e977f2d9_1787387543.jpg"},{"id":"xihulu","title":"西葫芦","summary":"煮软少量，温和纤维。","body":"无调味。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ee9c7738_1787387625.jpg"},{"id":"huacai","title":"花菜","summary":"煮软少量，产气可能让部分猫不适。","body":"完全煮熟、无调味。不是营养核心。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e832e961_1787387523.jpg"},{"id":"huanggua","title":"黄瓜","summary":"水分高，可少量解闷，营养贡献有限。","body":"洗干净去两端，切细条。不吃就不要强迫。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e84d56f2_1787387524.jpg"},{"id":"fanqie","title":"番茄","summary":"熟红番茄可极少；绿番茄和茎叶不要。","body":"未成熟部分含更多生物碱。红熟果肉少量通常更稳妥，仍非必需。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e7903129_1787387513.jpg"},{"id":"qiukui","title":"秋葵","summary":"煮软少量，黏液可能让部分猫厌恶。","body":"无调味煮软。不是营养核心。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ec758266_1787387591.jpg"}],"no":[{"id":"gulei","title":"菇类","summary":"猫是肉食为主，谷物不是必需。","body":"部分猫粮含谷物。单独喂饭、面包没有意义，还可能过敏或发胖。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e7e054ae_1787387518.jpg"},{"id":"dasuan","title":"大蒜","summary":"蒜比葱毒性风险更高。","body":"蒜蓉、蒜粉、调料包都要远离猫咪食物。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e73f2ee7_1787387507.jpg"},{"id":"yangcong","title":"洋葱","summary":"可能破坏红细胞，熟的同样危险。","body":"汤底和调料也要避开。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ef411e38_1787387636.jpg"},{"id":"shengjiang","title":"生姜","summary":"辛辣刺激，没有喂猫的理由。","body":"姜汤、姜片都不要。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ecfbe79e_1787387599.jpg"},{"id":"cong","title":"葱","summary":"葱属植物可能破坏红细胞。","body":"大葱、小葱、葱花、葱油都要避开。熟的同样危险。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e70a8180_1787387504.jpg"},{"id":"jiucai","title":"韭菜","summary":"葱属植物，熟的同样危险。","body":"饺子馅、炒菜里的韭菜都不要给。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e941d736_1787387540.jpg"},{"id":"lajiao","title":"辣椒","summary":"辣和刺激黏膜，没有好处。","body":"不要用辣条或火锅汤逗猫。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e9c9a984_1787387548.jpg"},{"id":"qingjiao","title":"青椒","summary":"青的更刺激，多数猫不吃。","body":"甜椒煮软优于青椒。整体非必需。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ec3e041e_1787387587.jpg"},{"id":"caijiao","title":"彩椒","summary":"熟软的甜椒可极少尝试，多数猫不吃。","body":"去掉蒂和籽，煮软无调味。辣椒素低的甜椒相对更稳妥，仍非必要食物。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e684e07e_1787387496.jpg"}]},{"t":"水果","ok":[{"id":"xigua","title":"西瓜","summary":"去籽果肉少量补水。","body":"籽和皮不要。糖分控制。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ee81affb_1787387624.jpg"},{"id":"mugua","title":"木瓜","summary":"熟软去籽少量，部分猫能接受。","body":"青木瓜和籽不合适。控制糖分。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895eaa6a121_1787387562.jpg"},{"id":"hamigua","title":"哈密瓜","summary":"去籽去皮少量果肉，多数猫可接受。","body":"糖分仍在，当零食控制量。腹泻停喂。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e7fab10c_1787387519.jpg"},{"id":"li","title":"梨","summary":"去核去籽少量果肉。","body":"籽不要给。糖分控制，腹泻停。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ea1d86b7_1787387553.jpg"},{"id":"xiangjiao","title":"香蕉","summary":"高钾高糖，少量即可。","body":"软的少量。不是每日必需。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ee4b2c6f_1787387620.jpg"},{"id":"caomei","title":"草莓","summary":"可极少，糖和农药残留要小心。","body":"洗干净去蒂，切碎极小块。不是营养必需，腹泻就停。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e69ef5f9_1787387497.jpg"},{"id":"lanmei","title":"蓝莓","summary":"洗干净少量浆果，部分猫喜欢。","body":"整颗噎住风险，压破更好。糖分仍要控制。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e9e52d95_1787387550.jpg"},{"id":"pingguo","title":"苹果","summary":"去核去籽少量果肉。","body":"籽不要给。切碎防噎。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ebb2ed2c_1787387579.jpg"},{"id":"huolongguo","title":"火龙果","summary":"果肉少量通常可，籽多、糖也不低。","body":"去皮少量。粪便变色可能只是色素，持续腹泻要停。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e88513fb_1787387528.jpg"},{"id":"yingtao","title":"樱桃","summary":"核不能给，果肉糖分高。","body":"去核后也没必要日常喂。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895efe394d2_1787387646.jpg"},{"id":"yezi","title":"椰子","summary":"脂肪高，椰肉和椰奶都不适合多给。","body":"不是补水方案。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895efc8ab6b_1787387644.jpg"},{"id":"pipa","title":"枇杷","summary":"核不能给，果肉糖分高。","body":"没有必要作为猫零食。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ebce6e0a_1787387580.jpg"},{"id":"shiliu","title":"石榴","summary":"籽多、酸，不适合。","body":"不要给石榴籽。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ed349c92_1787387603.jpg"}],"no":[{"id":"baixiangguo","title":"百香果","summary":"果肉酸，多数猫没兴趣，过量肠胃不适。","body":"不是毒性明星食物，但酸和籽都不适合当零食。清水更重要。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e64f0417_1787387492.jpg"},{"id":"niuyouguo","title":"牛油果","summary":"脂肪高，部分部位对动物不友好。","body":"不要把牛油果当猫零食。风险大于收益。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895eb626108_1787387574.jpg"},{"id":"mihoutao","title":"猕猴桃","summary":"酸、纤维多，可能肠胃刺激。","body":"多数猫不爱。不建议当常规零食。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ea8b28d0_1787387560.jpg"},{"id":"shizi","title":"柿子","summary":"涩和胃结石风险对猫没好处。","body":"不推荐。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ed54a961_1787387605.jpg"},{"id":"yangtao","title":"杨桃","summary":"对部分动物肾脏风险高。","body":"不要给杨桃。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ef932329_1787387641.jpg"},{"id":"lizhi","title":"荔枝","summary":"糖高，核不能给。","body":"不是猫需要的水果。极少量果肉也没必要日常喂。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ea388230_1787387555.jpg"},{"id":"jvzi","title":"橘子","summary":"柑橘类，精油和酸可能刺激。","body":"不要给皮和核。整体不推荐。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e993c80e_1787387545.jpg"},{"id":"putao","title":"葡萄","summary":"可能影响肾脏，剂量因个体而异。","body":"葡萄和葡萄干都不要。出现精神差、呕吐或少尿需尽快处理。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ebebf86d_1787387582.jpg"},{"id":"ningmeng","title":"柠檬","summary":"过酸，精油刺激。","body":"不要给柠檬片或柠檬水。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895eb11a2c9_1787387569.jpg"},{"id":"mangguo","title":"芒果","summary":"去核去皮少量，部分猫会过敏或不适。","body":"核很大不能给。糖分高，当零食要克制。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ea538e82_1787387557.jpg"},{"id":"chengzi","title":"橙子","summary":"柑橘精油和酸可能刺激。","body":"多数猫厌恶柑橘味。果肉少量通常风险低于果皮精油，仍不推荐当零食。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e6ef2010_1787387502.jpg"},{"id":"xiyou","title":"西柚","summary":"柑橘精油和药物相互作用风险。","body":"不要给西柚。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895eeed7f24_1787387630.jpg"},{"id":"shanzha","title":"山楂","summary":"过酸，核不能给。","body":"不适合猫。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ecc64ccc_1787387596.jpg"},{"id":"xingzi","title":"杏","summary":"核有风险，果肉糖分高。","body":"不要给核。整体非必需。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895eed397f1_1787387629.jpg"}]},{"t":"零食","ok":[{"id":"yangnai","title":"羊奶","summary":"部分猫比牛奶耐受，仍可能拉肚子。","body":"宠物配方羊奶优于餐桌羊奶。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ef5d2d12_1787387637.jpg"},{"id":"wurutangniunai","title":"无乳糖牛奶","summary":"比普通牛奶温和，仍非必需。","body":"专用猫奶更合适。大量仍可能胖。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895ee1522d6_1787387617.jpg"},{"id":"yuanweisuannai","title":"原味酸奶","summary":"乳糖仍在，糖和木糖醇要看配料。","body":"无糖原味也只是偶尔。多数猫不需要。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895f0191b5e_1787387649.jpg"},{"id":"nailao","title":"奶酪","summary":"乳糖和盐，多数成年猫不耐受。","body":"不是补钙良方。极小块原味奶酪也要看个体反应。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895eadc037d_1787387565.jpg"},{"id":"doufu","title":"豆腐","summary":"可极少，胀气和调味是主要问题。","body":"原味嫩豆腐煮一下，不要麻辣香锅里的豆腐。蛋白质来源仍以猫粮为准。","allowed":true,"imageUrl":"https://img.scdn.io/i/6a895e774f55e_1787387511.jpg"}],"no":[{"id":"niunai","title":"牛奶","summary":"多数成年猫乳糖不耐受。","body":"卡通里的牛奶不等于适合真猫。专用猫奶或清水更好。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895eb2c06d2_1787387570.jpg"},{"id":"huotuichang","title":"火腿肠","summary":"盐、淀粉、添加剂都很高。","body":"不要用人的火腿肠逗猫。选猫咪专用零食。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e8a01fdb_1787387530.jpg"},{"id":"shousi","title":"寿司","summary":"生鱼、芥末、盐和米饭都不合适。","body":"不要分享寿司。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ed6ed38d_1787387606.jpg"},{"id":"dangao","title":"蛋糕","summary":"糖、黄油、巧克力、木糖醇都可能有。","body":"人类甜点不适合猫。生日蛋糕尤其危险。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e72544f4_1787387506.jpg"},{"id":"youzhapin","title":"油炸品","summary":"高脂，胰腺炎风险。","body":"炸鸡、薯条都不要。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895effe4413_1787387647.jpg"},{"id":"guazi","title":"瓜子","summary":"盐、壳和脂肪都不适合。","body":"磕瓜子是人的零食。壳可能卡住，盐加重饮水负担。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e7c4c7e0_1787387516.jpg"},{"id":"jianguo","title":"坚果","summary":"脂肪高，部分坚果还有霉菌风险。","body":"核桃、杏仁、花生都不适合当猫零食。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e8b9f1b9_1787387531.jpg"},{"id":"qiaokeli","title":"巧克力","summary":"含可可碱，猫咪无法有效代谢。","body":"黑巧更高风险。即使少量也不应投喂。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ec071fac_1787387584.jpg"},{"id":"qipaoshui","title":"气泡水","summary":"气体和添加都不适合。","body":"不要给汽水。清水即可。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ec5a1738_1787387589.jpg"},{"id":"bingqilin","title":"冰淇淋","summary":"乳糖、糖和脂肪都对猫不友好。","body":"不要分享人类冰淇淋。乳糖不耐受很常见，巧克力味更危险。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e669d78d_1787387494.jpg"},{"id":"xuegao","title":"雪糕","summary":"糖、奶、巧克力涂层都不行。","body":"不要分享。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ef08b13b_1787387632.jpg"},{"id":"kafei","title":"咖啡","summary":"咖啡因对猫不安全。","body":"咖啡、拿铁、咖啡渣都不能接触。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e9ae71f7_1787387546.jpg"},{"id":"chalei","title":"茶类","summary":"咖啡因和茶碱对猫不安全。","body":"茶、奶茶、茶饮料都不要给。误饮大量需联系专业机构。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e6ba97ab_1787387499.jpg"},{"id":"yuebing","title":"月饼","summary":"糖油盐和蛋黄莲蓉都不适合。","body":"过节不要投喂。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895f03410ab_1787387651.jpg"},{"id":"jiujing","title":"酒精","summary":"猫咪无法安全代谢酒精。","body":"啤酒、料酒、醉虾汤汁都要远离。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895e95c7c83_1787387541.jpg"},{"id":"naicha","title":"奶茶","summary":"茶碱、糖、奶精都不适合。","body":"珍珠奶茶更危险。只给清水。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895eac1a354_1787387564.jpg"},{"id":"mifengshui","title":"蜂蜜水","summary":"糖高，对猫没有益处。","body":"不要用蜂蜜水「润嗓」或补营养。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895ea70d61a_1787387559.jpg"},{"id":"tangguo","title":"糖果","summary":"糖和木糖醇风险。","body":"无糖糖果更危险。","allowed":false,"imageUrl":"https://img.scdn.io/i/6a895eda50fd3_1787387610.jpg"}]}];
